import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const p="/assets/alsamixer.png",y=JSON.parse('{"title":"Archlinux下声卡的设置与折腾","description":"","frontmatter":{"title":"Archlinux下声卡的设置与折腾","date":"2014-06-05 09:22","comments":true,"archives":2014,"tags":["linux"]},"headers":[],"relativePath":"posts/2014-06-05-archlinux-sound-setting/index.md","filePath":"posts/2014/2014-06-05-Archlinux-sound-setting.md"}'),o={name:"posts/2014-06-05-archlinux-sound-setting/index.md"};function r(c,s,t,i,d,u){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>最近又有瞎折腾装 Arch....发现显卡驱动的安装和设置都不是问题... 声卡却老是出现奇怪的问题,便把最近折腾的经验写下来吧~</p><h2 id="切换默认声卡" tabindex="-1">切换默认声卡 <a class="header-anchor" href="#切换默认声卡" aria-label="Permalink to &quot;切换默认声卡&quot;">​</a></h2><p>发现最近的新本子基本上声卡设备都不止一个,个人猜测应该是 HDMI 音频输出和 本机主板上的音频输出吧.可以使用 <code>aplay -l</code> 命令显示所有声卡设备. 我机器的输出是:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">[acgotaku@Archlinux </span><span style="color:#D73A49;">~</span><span style="color:#24292E;">]$ aplay -l</span></span>
<span class="line"><span style="color:#D73A49;">****</span><span style="color:#24292E;"> List of PLAYBACK Hardware Devices </span><span style="color:#D73A49;">****</span></span>
<span class="line"><span style="color:#6F42C1;">card</span><span style="color:#032F62;"> 0:</span><span style="color:#032F62;"> HDMI</span><span style="color:#24292E;"> [HDA </span><span style="color:#032F62;">Intel</span><span style="color:#032F62;"> HDMI],</span><span style="color:#032F62;"> device</span><span style="color:#032F62;"> 3:</span><span style="color:#032F62;"> HDMI</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;"> [HDMI </span><span style="color:#032F62;">0]</span></span>
<span class="line"><span style="color:#6F42C1;">  Subdevices:</span><span style="color:#032F62;"> 1/1</span></span>
<span class="line"><span style="color:#6F42C1;">  Subdevice</span><span style="color:#6A737D;"> #0: subdevice #0</span></span>
<span class="line"><span style="color:#6F42C1;">card</span><span style="color:#032F62;"> 1:</span><span style="color:#032F62;"> PCH</span><span style="color:#24292E;"> [HDA </span><span style="color:#032F62;">Intel</span><span style="color:#032F62;"> PCH],</span><span style="color:#032F62;"> device</span><span style="color:#032F62;"> 0:</span><span style="color:#032F62;"> ALC3220</span><span style="color:#032F62;"> Analog</span><span style="color:#24292E;"> [ALC3220 </span><span style="color:#032F62;">Analog]</span></span>
<span class="line"><span style="color:#6F42C1;">  Subdevices:</span><span style="color:#032F62;"> 1/1</span></span>
<span class="line"><span style="color:#6F42C1;">  Subdevice</span><span style="color:#6A737D;"> #0: subdevice #0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>第一个一般为默认的声卡输出设备,显然 HDMI 输出是不对的,导致声音无法正常播放,我们应该把默认声卡切换为 第二个.最简单易用的方法是在用户根目录下新建一个 .asoundrc 文件.输入以下内容:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>defaults.pcm.card 1</span></span>
<span class="line"><span>defaults.pcm.device 0</span></span>
<span class="line"><span>defaults.ctl.card 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>上面的数据可以从声卡设备输出中找到,这样就切换到 card 1 的 device 0 设备了.不过切换之后可能发现还是没有 声音,因为 alsa 默认是静音的需要手动解除才行. 这就需要去官方源安装 <code>alsamixer</code> 工具. <a href="https://www.archlinux.org/packages/?name=alsa-utils" target="_blank" rel="noreferrer">alsa-utils</a> 我自己安装的 alsamixer 使用界面是:</p><p><img src="`+p+'" alt="alsamixer"></p><p>默认 Master 竖条下方显示的不是 00 而是 MM,表示是静音的,按下 m 键解除静音.</p><h2 id="耳机有持续的杂音的解决方案" tabindex="-1">耳机有持续的杂音的解决方案 <a class="header-anchor" href="#耳机有持续的杂音的解决方案" aria-label="Permalink to &quot;耳机有持续的杂音的解决方案&quot;">​</a></h2><p>有些情况下即使安装好 alsa 解除静音了,但仍然发现戴耳机的时候没有任何软件发声的时候会有持续的杂音,但是音乐播放器一旦放音乐的时候杂音又消失了. 这个问题的原因是 alsa 默认设置 Mic 声道是静音的,我们只需要解除 Mic 声道的静音并调节至合适的值即可.</p><h2 id="恢复默认的-alsa-设置" tabindex="-1">恢复默认的 alsa 设置 <a class="header-anchor" href="#恢复默认的-alsa-设置" aria-label="Permalink to &quot;恢复默认的 alsa 设置&quot;">​</a></h2><p>有些时候自己胡乱设置导致 alsa 无法正常工作的时候可以通过使用 <code>alsactl restore</code> 命令使 alsa 恢复到默认的配置一般都能正常工作了.</p>',13)])])}const m=a(o,[["render",r]]);export{y as __pageData,m as default};
